		}

		if (formatEl) {
			actions.push(A.prevent());

			/** @type {HTMLElement} */
			if (selectRange) {
				// RTL bidi edge correction for selection ranges (formatStartEdge only)
				// formatEndEdge insert-after behavior is already correct for RTL selections
				if (ctx.options.get('_rtl') && formatStartEdge && !formatEndEdge) {
					const _wd = ctx.fc.get('_wd');
					const testRange = _wd.createRange();
					testRange.setStart(range.startContainer, range.startOffset);
					testRange.collapse(true);
					if (isRtlBidiMismatch(testRange, formatEl, 'front', _wd)) {
						formatStartEdge = false;
						formatEndEdge = true;
						bidiSwapped = true;
					}
				}
				actions.push(A.enterFormatBreakWithSelection(formatEl, range, formatStartEdge, formatEndEdge));
			} else {
				actions.push(A.enterFormatBreakAtCursor(formatEl, range));
			}

			actions.push(A.caretScrollTo(range));
			return true;
		}
	}

	if (selectRange) {
		actions.push(A.caretScrollTo(range));
		return true;
	}

	if (
		rangeEl &&
		dom.query.getParentElement(rangeEl, 'FIGCAPTION') &&
		dom.query.getParentElement(rangeEl, dom.check.isList)
	) {
		ports.enterPrevent(e);
		actions.push(A.enterFigcaptionExitInList(formatEl));
		actions.push(A.caretScrollTo(range));
	}

	return true;
}

function CreateToolBar(buttonList, plugins, options, icons, lang, isUpdate) {
	/** create button list */
	buttonList = JSON.parse(JSON.stringify(buttonList));
	const defaultButtonList = _defaultButtons(options.get('_rtl'), icons, lang);
	/** @type {Object<string, Array<HTMLElement>>} */
	const pluginCallButtons = {};
	const responsiveButtons = [];
	const updateButtons = [];

	let modules = null;
	let button = null;
	let plugin = null;
	let moduleElement = null;
	let buttonElement = null;
	// let vertical = false;
	const moreLayer = dom.utils.createElement('DIV', { class: 'se-toolbar-more-layer' });
	const buttonTray = dom.utils.createElement('DIV', { class: 'se-btn-tray' });
	const separator_vertical = dom.utils.createElement('DIV', { class: 'se-toolbar-separator-vertical' });

	buttonGroupLoop: for (let i = 0, more, moreContainer, moreCommand, buttonGroup, align; i < buttonList.length; i++) {
		more = false;
		align = '';
		buttonGroup = buttonList[i];
		moduleElement = _createModuleGroup();

		// button object
		if (typeof buttonGroup === 'object') {
			// buttons loop
			for (let j = 0, moreButton; j < buttonGroup.length; j++) {
				button = buttonGroup[j];
				moreButton = false;
				plugin = plugins[button];

				if (/^%\d+/.test(button) && j === 0) {
					buttonGroup[0] = button.replace(/[^\d]/g, '');
					responsiveButtons.push(buttonGroup);
					buttonList.splice(i--, 1);
					continue buttonGroupLoop;
				}
				if (typeof plugin === 'function') {
					modules = [plugin.className, plugin.title, button, plugin.type, plugin.innerHTML, plugin._disabled];
				} else if (typeof plugin === 'object') {
					const originFnc = plugin.constructor;
					modules = [
						plugin.className || originFnc.className,
						plugin.title || originFnc.title,
						button,
						plugin.type || originFnc.type,
						plugin.innerHTML || originFnc.innerHTML,
						plugin._disabled || originFnc._disabled,
					];
				} else {
					// align
					if (/^-/.test(button)) {
						align = button.substring(1);
						moduleElement.div.className += ' module-float-' + align;
						continue;
					}

					// rtl fix
					if (/^#/.test(button)) {
						const option = button.substring(1);
						if (option === 'fix') moduleElement.ul.className += ' se-menu-dir-fix';
						continue;
					}

					// more button
					if (/^:/.test(button)) {
						moreButton = true;
						const matched = button.match(/^:([^-]+)-([^-]+)/);
						moreCommand = '__se__more_' + i;
						const title = matched[1].trim();
						const innerHTML = matched[2].trim();
						modules = [
							'se-btn-more',
							/^lang\./i.test(title) ? lang[title.replace(/^lang\./i, '')] : title,
							moreCommand,
							'MORE',
							innerHTML,
						];
					} else if (button === '|') {
						// separator vertical
						modules = ['se-toolbar-separator-vertical', '', '', 'separator', ''];
					} else {
						// default command
						if (button === 'copy' && !env.isClipboardSupported) {
							console.warn(
								'[SUNEDITOR.constructor.warn] Clipboard is not supported in this browser. : [copy] button is not rendered.',
							);
						}
						modules = defaultButtonList[button];
					}

					if (!modules) {
						if (!plugin)
							throw Error(
								`[SUNEDITOR.create.toolbar.fail] The button name of a plugin that does not exist. [${button}]`,
							);
						plugin = typeof plugin === 'object' ? plugin.constructor : plugin;
						modules = [
							plugin.className,
							plugin.title,
							plugin.key,
							plugin.type,
							plugin.innerHTML,
							plugin._disabled,
						];
					}
				}

				buttonElement = _createButton(
					modules[0],
					modules[1],
					modules[2],
					modules[3],
					modules[4],
					modules[5],
					icons,
				);
				(more ? moreContainer : moduleElement.ul).appendChild(buttonElement.li);

				if (plugin) {
					if (pluginCallButtons[button]) {
						pluginCallButtons[button].push(buttonElement.button);
					} else {
						pluginCallButtons[button] = [buttonElement.button];
					}

					if (isUpdate) {
						updateButtons.push({ button: buttonElement.button, plugin, key: button });
					}
				}

				// more button
				if (moreButton) {
					more = true;
					moreContainer = dom.utils.createElement('DIV');
					moreContainer.className = 'se-more-layer ' + moreCommand;
					moreContainer.setAttribute('data-ref', moreCommand);
					moreContainer.innerHTML =
						'<div class="se-more-form"><ul class="se-menu-list"' +
						(align ? ' style="float: ' + align + ';"' : '') +
						'></ul></div>';
					moreLayer.appendChild(moreContainer);
					moreContainer = moreContainer.firstElementChild.firstElementChild;
				}
			}

			// if (vertical) {
			// 	const sv = separator_vertical.cloneNode(false);
			// 	buttonTray.appendChild(sv);
			// }

			buttonTray.appendChild(moduleElement.div);
			// vertical = true;
		} else if (buttonGroup === '|') {
			// // separator vertical
			const sv = separator_vertical.cloneNode(false);
			buttonTray.appendChild(sv);
			continue;
		} else if (/^\/$/.test(buttonGroup)) {
			/** line break  */
			const enterDiv = dom.utils.createElement('DIV', { class: 'se-btn-module-enter' });
			buttonTray.appendChild(enterDiv);
			// vertical = false;
		}
	}

	switch (buttonTray.children.length) {
		case 0:
			buttonTray.style.display = 'none';
			break;
		case 1:
			dom.utils.removeClass(buttonTray.firstElementChild, 'se-btn-module-border');
			break;
	}

	if (moreLayer.children.length > 0) buttonTray.appendChild(moreLayer);
	if (responsiveButtons.length > 0) responsiveButtons.unshift(buttonList);

	_applyToolbarInnerWidth(buttonTray, options.get('toolbar_innerWidth'));

	// rendering toolbar
	const tool_bar = dom.utils.createElement(
		'DIV',
		{ class: 'se-toolbar sun-editor-common' + (!options.get('shortcutsHint') ? ' se-shortcut-hide' : '') },
		buttonTray,
	);

	if (options.get('toolbar_hide')) tool_bar.style.display = 'none';

	return {
		element: tool_bar,
		pluginCallButtons,
		responsiveButtons,
		buttonTray,
		updateButtons,
	};
}

async function OnClick_wysiwyg(fc, e) {
	const eventTarget = dom.query.getEventTarget(e);

	if (fc.get('isReadOnly')) {
		e.preventDefault();
		if (dom.check.isAnchor(eventTarget)) {
			_w.open(eventTarget.href, eventTarget.target);
		}
		return false;
	}

	if (dom.check.isNonEditable(fc.get('wysiwyg'))) return;

	// user event
	if ((await this.$.eventManager.triggerEvent('onClick', { frameContext: fc, event: e })) === false) return;
	// plugin event
	if ((await this._callPluginEventAsync('onClick', { frameContext: fc, event: e })) === false) return;

	// component
	const componentInfo = this.$.component.get(eventTarget);
	if (componentInfo) {
		e.preventDefault();
		this.$.component.select(componentInfo.target, componentInfo.pluginName);
		return;
	}

	this.$.selection.init();

	if (e.detail === 3) {
		const range = this.$.selection.getRange();
		if (this.$.format.isLine(range.endContainer) && range.endOffset === 0) {
			this.$.selection.setRange(
				range.startContainer,
				range.startOffset,
				range.startContainer,
				range.startContainer.textContent.length,
			);
		}
	}

	const selectionNode = this.$.selection.getNode();
	const formatEl = this.$.format.getLine(selectionNode, null);
	const rangeEl = this.$.format.getBlock(selectionNode, null);
	if (!formatEl && !dom.check.isNonEditable(eventTarget) && !dom.check.isList(rangeEl)) {
		const range = this.$.selection.getRange();
		if (this.$.format.getLine(range.startContainer) === this.$.format.getLine(range.endContainer)) {
			if (dom.check.isList(rangeEl)) {
				e.preventDefault();
				const prevLi = selectionNode.nextElementSibling;
				const oLi = dom.utils.createElement('LI', null, selectionNode);
				rangeEl.insertBefore(oLi, prevLi);
				this.$.focusManager.focus();
			} else if (
				!dom.check.isWysiwygFrame(selectionNode) &&
				!this.$.component.is(selectionNode) &&
				(!dom.check.isTableElements(selectionNode) || dom.check.isTableCell(selectionNode)) &&
				this._setDefaultLine(this.$.format.isBlock(rangeEl) ? 'DIV' : this.$.options.get('defaultLine')) !==
					null
			) {
				e.preventDefault();
				this.$.focusManager.focus();
			}
		}
	}

	// copy format
	this.$.commandDispatcher._copyFormat();

	// Defer balloon toggle — selection range is finalized after mouseup event returns
	if (this.$.store.mode.isBalloon || this.$.store.mode.isSubBalloon)
		_w.setTimeout(this._toggleToolbarBalloon.bind(this), 0);
}
